-- termboss.lua -- generated by `term-boss setup wezterm`. Overwritten on each run; do not edit.
--
-- Wire it up in wezterm.lua:
--   require('termboss').apply_to_config(config)
--
-- WezTerm only auto-reloads its config in windows that already had a config file when they
-- started. In a window opened before wezterm.lua existed, press Ctrl+Shift+R or reopen it.
--
-- term-boss sets two per-pane user vars (OSC 1337 SetUserVar):
--   TAB_COLOR  '#rrggbb' tab background, '' to clear
--   TAB_BADGE  text shown in the right status area, '' to clear
local wezterm = require 'wezterm'

local M = {}

local function nonempty(s)
  if s ~= nil and s ~= '' then
    return s
  end
  return nil
end

-- Black text on light tab colours, white on dark ones.
local function fg_for(hex)
  local r = tonumber(hex:sub(2, 3), 16) or 0
  local g = tonumber(hex:sub(4, 5), 16) or 0
  local b = tonumber(hex:sub(6, 7), 16) or 0
  if (0.299 * r + 0.587 * g + 0.114 * b) > 150 then
    return '#000000'
  end
  return '#ffffff'
end

-- tab.active_pane is a PaneInformation: user_vars is a plain field here.
function M.format_tab_title(tab, tabs, panes, config, hover, max_width)
  local pane = tab.active_pane
  local title = nonempty(tab.tab_title) or pane.title
  local color = nonempty(pane.user_vars.TAB_COLOR)
  local result = {}
  if color then
    table.insert(result, { Background = { Color = color } })
    table.insert(result, { Foreground = { Color = fg_for(color) } })
  end
  -- Reserve the two padding cells so the title never exceeds the space wezterm allocated.
  local available = math.max(max_width - 2, 0)
  title = wezterm.truncate_right(title, available)
  table.insert(result, { Text = ' ' .. title .. ' ' })
  return result
end

-- pane here is a Pane object: user vars come from a method. The pane may already be gone when
-- the event fires (a tab was just closed), in which case get_user_vars raises; just skip.
function M.update_status(window, pane)
  local ok, vars = pcall(pane.get_user_vars, pane)
  if not ok or not vars then
    return
  end
  local badge = nonempty(vars.TAB_BADGE)
  if badge then
    window:set_right_status(wezterm.format {
      { Attribute = { Intensity = 'Bold' } },
      { Text = ' ' .. badge .. ' ' },
    })
  else
    window:set_right_status('')
  end
end

function M.apply_to_config(config)
  wezterm.on('format-tab-title', M.format_tab_title)
  wezterm.on('update-status', M.update_status)
  -- Repaint the status immediately instead of waiting for the next tick; also logs for debugging
  -- (visible in the debug overlay, Ctrl+Shift+L).
  wezterm.on('user-var-changed', function(window, pane, name, value)
    if name == 'TAB_COLOR' or name == 'TAB_BADGE' then
      wezterm.log_info('termboss: ' .. name .. '=' .. tostring(value))
      M.update_status(window, pane)
    end
  end)
  return config
end

return M
